import BasicLayout from '@/components/layout/BasicLayout';
import { Head as BaseHead } from '@/components/PageMeta';
import React from 'react';
import { FaXmark } from 'react-icons/fa6';
import CTA from './components/CTA';
import Footer from './components/Footer';
import Hero from './components/Hero';
import Integration from './components/Integration';
import Media from './components/Media';
import Navbar from './components/Navbar';
import Post from './components/Post';
import Services from './components/Services';
import Testimonial from './components/Testimonial';
import Work from './components/Work';

export const FORM_URL =
  'https://webview.smax.ai/public/69ce2d1d0c7f3f53a3edbd20?page_id=fb816898231517528&type=embedded';

// Redirect URL built from form config (page_id fb816898231517528 → 816898231517528)
export const MESSENGER_REDIRECT_URL = 'https://m.me/816898231517528';

const index = () => {
  const iframeRef = React.useRef<HTMLIFrameElement>(null);
  const formLoadedRef = React.useRef(false);

  // Final approach: watch iframe DOM changes via MutationObserver on the parent document
  // When the iframe element itself gets a new src attribute or navigates, catch it
  React.useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe) return;

    // Track iframe src attribute changes
    const observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        for (const record of mutation.addedNodes) {
          if (record === iframe) {
            // iframe was re-added or src changed — check if it's an external URL
            const currentSrc = iframe.getAttribute('src');
            if (
              currentSrc &&
              !currentSrc.includes('smax.ai') &&
              !currentSrc.includes('webview.smax') &&
              currentSrc.startsWith('http')
            ) {
              window.open(currentSrc, '_blank');
              iframe.setAttribute('src', FORM_URL);
            }
          }
        }
      }
    });

    observer.observe(document.body, { childList: true, subtree: true });

    // Also check on every iframe load event
    const handleLoad = () => {
      if (!formLoadedRef.current) {
        formLoadedRef.current = true;
        return; // first load — it's the form itself, skip
      }

      // Re-check after form submits — iframe URL may have changed to external site
      try {
        const iframeWin = iframe.contentWindow;
        if (!iframeWin) return;

        const href = (iframeWin as any).location?.href;
        if (
          href &&
          href !== 'about:blank' &&
          href !== FORM_URL &&
          !href.includes('smax.ai') &&
          !href.includes('webview.smax')
        ) {
          window.open(href, '_blank');
          // Reset iframe back to form
          iframe.setAttribute('src', 'about:blank');
          setTimeout(() => iframe.setAttribute('src', FORM_URL), 100);
          formLoadedRef.current = false;
        }
      } catch {
        // Cross-origin — iframe navigated to external domain → open in new tab
        window.open(MESSENGER_REDIRECT_URL, '_blank');
        iframe.setAttribute('src', 'about:blank');
        setTimeout(() => iframe.setAttribute('src', FORM_URL), 100);
        formLoadedRef.current = false;
      }
    };

    iframe.addEventListener('load', handleLoad);
    return () => {
      observer.disconnect();
      iframe.removeEventListener('load', handleLoad);
    };
  }, []);

  // Intercept any postMessage too (belt + suspenders)
  React.useEffect(() => {
    const handleMessage = (e: MessageEvent) => {
      const data = e.data;
      if (!data) return;

      const url =
        (data as any).__smax_redirect ||
        (data as any).url ||
        (data as any).redirectUrl ||
        (data as any).redirect;

      if (url && typeof url === 'string' && url.startsWith('http')) {
        window.open(url, '_blank');
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  return (
    <>
      <BasicLayout>
        <div className="body">
          <Navbar />
          <Hero />
          <Post />
          <Work />
          <Services />
          <Media />
          <Integration />
          <Testimonial />
          <CTA />
          <Footer />
        </div>
        <div id="cdp-form-modal" className="cdp-modal">
          <a href="#" className="cdp-modal-close" aria-label="Close">
            <FaXmark />
          </a>
          <iframe
            ref={iframeRef}
            className="cdp-modal-iframe"
            src={FORM_URL}
            style={{ border: 'none' }}
            sandbox="allow-forms allow-scripts allow-same-origin allow-popups"
            allowFullScreen
          ></iframe>
        </div>
      </BasicLayout>
    </>
  );
};

export default index;

export const Head = () => {
  return (
    <>
      <BaseHead />
      <script async src="https://www.googletagmanager.com/gtag/js?id=G-2F3475PKS2"></script>
      <script
        dangerouslySetInnerHTML={{
          __html: `
            window.dataLayer = window.dataLayer || [];
            function gtag(){dataLayer.push(arguments);}
            gtag('js', new Date());
            gtag('config', 'G-2F3475PKS2');
          `,
        }}
      />
      <script
        dangerouslySetInnerHTML={{
          __html: `
            window.smAsyncInit = function () {
                SM.init({
                    page_pid: 'ctm6969f7e5201d11639818ddde',
                    trigger_id: '696a0222de67b4f660cb50d7',
                    chat_type: 'PLUGIN',
                    env: 'prod'
                })
            }
          `,
        }}
      />
      <script async defer src="https://chatbox.smax.ai/sdk.min.js"></script>
      
    </>
  );
};
